"""B2005, listening card 20 (main, 2026-11-25; data-free): the group G_k generated by C and sigma on the orbit of (3,3,3)
mod 3^k (k = 2..5). S1: its order and the stabiliser of (3,3,3) (sympy Schreier-Sims). S2: whether rho (rho(C) = omega,
rho(sigma) = -1) factors through G_k (a breadth-first walk over all elements, each labelled by rho, labels checked for
consistency). S3: G_2's element orders. S4: the order of G_k's abelianisation.
    python3 -B small_group.py > small_group_run.txt"""
import contextlib, io, pathlib, time
from collections import Counter, deque
import numpy as np
from sympy.combinatorics import Permutation, PermutationGroup
HERE = pathlib.Path(__file__).resolve().parent
src = (HERE.parent.parent / "B2004_listening_19_the_mechanism_of_the_halving_the_modular_group_and_its_order_six_character" / "verification" / "mechanism.py").read_text().split("WORDS = words(10)")[0]
ns = {"__file__": str(HERE / "small_group.py")}
with contextlib.redirect_stdout(io.StringIO()): exec(compile(src, "b2004_head", "exec"), ns)
t0 = time.time()
for k in (2, 3, 4, 5):
    N = 3 ** k
    pts, idx, pC, pS, moves = ns["orbit"](N, (3, 3, 3)); n = len(pts)
    G = PermutationGroup([Permutation([int(i) for i in pC]), Permutation([int(i) for i in pS])])
    order = G.order(); i0 = idx[(3, 3, 3)]; St = G.stabilizer(i0); so = St.order()
    stab_is_C = so == 3 and Permutation([int(i) for i in pC]) in St
    ab = order // G.derived_subgroup().order()
    print("mod %d (k = %d): orbit %d points; |G_k| = %d (8 * 3^(2k-3) = %d); stabiliser of (3,3,3) has order %d and is <C>: %s; abelianisation order %d  [%.0f s]" % (
        N, k, n, order, 8 * 3 ** (2 * k - 3), so, stab_is_C, ab, time.time() - t0), flush=True)
    # S2: rho on every element
    dt = np.int16 if n < 32000 else np.int32
    e = np.arange(n, dtype=dt); gens = [(pC.astype(dt), 2), (pS.astype(dt), 3)]
    label = {e.tobytes(): 0}; q = deque([e]); consistent = True; bad = None; orders = Counter()
    while q:
        g = q.popleft(); r = label[g.tobytes()]
        for s, es in gens:
            h = s[g]; key = h.tobytes(); rh = (r + es) % 6
            if key in label:
                if label[key] != rh and consistent: consistent = False; bad = (label[key], rh)
            else:
                label[key] = rh; q.append(h)
    print("    walk: %d elements (equals |G_k|: %s); rho factors through G_k (labels consistent): %s%s  [%.0f s]" % (
        len(label), len(label) == order, consistent, "" if consistent else "; first clash: rho exponents %s" % (bad,), time.time() - t0), flush=True)
    if k == 2:
        for key in label:
            g = np.frombuffer(key, dtype=dt); p = g.copy(); o = 1
            while not np.array_equal(p, e): p = g[p]; o += 1
            orders[o] += 1
        print("    S3: G_2's element orders %s; S4's are {1: 1, 2: 9, 3: 8, 4: 6}: %s" % (dict(sorted(orders.items())), dict(orders) == {1: 1, 2: 9, 3: 8, 4: 6}))
